			function doList(psStatus){
			    console.log("dmSearch = ", app.lookup("dmSearch").getDatas());
			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess){
			        if(pbSuccess) {
			            var dsList = app.lookup("dsList");
			            for(var i = 0; i < dsList.getRowCount(); i++){
			                dsList.setValue(i, "STDNT_BRTH_YMD"         , dateForm(dsList.getValue(i, "STDNT_BRTH_YMD")));
			                dsList.setValue(i, "STDNT_MBL_TELNO_ENCPT"  , tellForm(dsList.getValue(i, "STDNT_MBL_TELNO_ENCPT")));
			                dsList.setValue(i, "STDNT_ADDR"             , dsList.getValue(i, "STDNT_ADDR").replaceAll("\n", " "));
			                dsList.setValue(i, "STTY_AGT_CTTPC_TELNO"   , tellForm(dsList.getValue(i, "STTY_AGT_CTTPC_TELNO")));
			            }
			            
			            if(psStatus == "save"){
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            }else{
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			        }
			    });
			    util.Control.redraw(app, "grpData"); 
			}

